 1	/**
 2	 * Unit tests for the api.workspaces.openVscode and
 3	 * api.workspaces.openGithubDesktop methods in api.js.
 4	 *
 5	 * Uses Node's built-in test runner and a lightweight fetch mock.
 6	 * Run individually with:
 7	 *   node --test gui/public/js/api.workspaces.launch.test.mjs
 8	 */
 9	
10	import { test, before, afterEach } from 'node:test';
11	import assert from 'node:assert/strict';
12	
13	// ---------------------------------------------------------------------------
14	// fetch mock infrastructure
15	// ---------------------------------------------------------------------------
16	
17	/**
18	 * Captured calls made to the mocked fetch.
19	 * @type {{ method: string, url: string, body?: unknown }[]}
20	 */
21	const calls = [];
22	
23	/**
24	 * The response the next fetch call should simulate.
25	 * @type {{ status: number, body?: unknown, contentType?: string }}
26	 */
27	let nextResponse = { status: 200, body: { success: true }, contentType: 'application/json' };
28	
29	/**
30	 * Install a global fetch mock before any test runs.
31	 * The mock records the URL, method, and body, then returns the value of `nextResponse`.
32	 */
33	before(() => {
34	    globalThis.fetch = async (url, options = {}) => {
35	        const rawBody = options.body;
36	        calls.push({
37	            method: options.method ?? 'GET',
38	            url: String(url),
39	            body: rawBody ? JSON.parse(rawBody) : undefined,
40	        });
41	
42	        const { status, body, contentType = 'application/json' } = nextResponse;
43	        const bodyText = body !== undefined ? JSON.stringify(body) : '';
44	
45	        return {
46	            status,
47	            ok: status >= 200 && status < 300,
48	            statusText: 'OK',
49	            headers: {
50	                get(name) {
51	                    if (name === 'Content-Type') return contentType;
52	                    return null;
53	                },
54	            },
55	            json() {
56	                return Promise.resolve(JSON.parse(bodyText));
57	            },
58	        };
59	    };
60	});
61	
62	/** Reset captured calls and the next-response configuration after each test. */
63	afterEach(() => {
64	    calls.length = 0;
65	    nextResponse = { status: 200, body: { success: true }, contentType: 'application/json' };
66	});
67	
68	// ---------------------------------------------------------------------------
69	// Import the module under test
70	// ---------------------------------------------------------------------------
71	
72	const { api } = await import('./api.js');
73	
74	// ---------------------------------------------------------------------------
75	// Structure tests
76	// ---------------------------------------------------------------------------
77	
78	test('api.workspaces.openVscode is exported as a function', () => {
79	    assert.equal(typeof api.workspaces.openVscode, 'function');
80	});
81	
82	test('api.workspaces.openGithubDesktop is exported as a function', () => {
83	    assert.equal(typeof api.workspaces.openGithubDesktop, 'function');
84	});
85	
86	// ---------------------------------------------------------------------------
87	// api.workspaces.openVscode()
88	// ---------------------------------------------------------------------------
89	
90	test('openVscode() sends POST to the correct URL', async () => {
91	    await api.workspaces.openVscode('my-project', 'my-workspace');
92	
93	    assert.equal(calls.length, 1, 'exactly one fetch call expected');
94	    assert.equal(calls[0].method, 'POST');
95	    assert.equal(calls[0].url, '/api/projects/my-project/workspaces/my-workspace/launch/vscode');
96	});
97	
98	test('openVscode() encodes special characters in projectId and wid', async () => {
99	    await api.workspaces.openVscode('proj/a b', 'ws/x y');

100	
101	    assert.equal(calls[0].url, '/api/projects/proj%2Fa%20b/workspaces/ws%2Fx%20y/launch/vscode');
102	});
103	
104	test('openVscode() sends no request body', async () => {
105	    await api.workspaces.openVscode('my-project', 'my-workspace');
106	
107	    assert.equal(calls[0].body, undefined, 'no request body should be sent');
108	});
109	
110	test('openVscode() returns the parsed JSON response', async () => {
111	    nextResponse = { status: 200, body: { success: true }, contentType: 'application/json' };
112	
113	    const result = await api.workspaces.openVscode('my-project', 'my-workspace');
114	
115	    assert.deepEqual(result, { success: true });
116	});
117	
118	test('openVscode() throws on non-2xx response', async () => {
119	    nextResponse = { status: 500, body: { error: 'launch failed' }, contentType: 'application/json' };
120	
121	    await assert.rejects(
122	        () => api.workspaces.openVscode('my-project', 'my-workspace'),
123	        (err) => {
124	            assert.equal(err.message, 'launch failed');
125	            return true;
126	        },
127	    );
128	});
129	
130	// ---------------------------------------------------------------------------
131	// api.workspaces.openGithubDesktop()
132	// ---------------------------------------------------------------------------
133	
134	test('openGithubDesktop() sends POST to the correct URL', async () => {
135	    await api.workspaces.openGithubDesktop('my-project', 'my-workspace', 'my-repo');
136	
137	    assert.equal(calls.length, 1, 'exactly one fetch call expected');
138	    assert.equal(calls[0].method, 'POST');
139	    assert.equal(calls[0].url, '/api/projects/my-project/workspaces/my-workspace/launch/github-desktop/my-repo');
140	});
141	
142	test('openGithubDesktop() encodes special characters in all three path parameters', async () => {
143	    await api.workspaces.openGithubDesktop('proj/a b', 'ws/x y', 'repo/z w');
144	
145	    assert.equal(
146	        calls[0].url,
147	        '/api/projects/proj%2Fa%20b/workspaces/ws%2Fx%20y/launch/github-desktop/repo%2Fz%20w',
148	    );
149	});
150	
151	test('openGithubDesktop() sends no request body', async () => {
152	    await api.workspaces.openGithubDesktop('my-project', 'my-workspace', 'my-repo');
153	
154	    assert.equal(calls[0].body, undefined, 'no request body should be sent');
155	});
156	
157	test('openGithubDesktop() returns the parsed JSON response', async () => {
158	    nextResponse = { status: 200, body: { success: true }, contentType: 'application/json' };
159	
160	    const result = await api.workspaces.openGithubDesktop('my-project', 'my-workspace', 'my-repo');
161	
162	    assert.deepEqual(result, { success: true });
163	});
164	
165	test('openGithubDesktop() throws on non-2xx response', async () => {
166	    nextResponse = { status: 500, body: { error: 'app not installed' }, contentType: 'application/json' };
167	
168	    await assert.rejects(
169	        () => api.workspaces.openGithubDesktop('my-project', 'my-workspace', 'my-repo'),
170	        (err) => {
171	            assert.equal(err.message, 'app not installed');
172	            return true;
173	        },
174	    );
175	});

